<?php require_once __DIR__.'/includes/bootstrap.php';require_login();$u=current_user();$rows=$db?$db->prepare('SELECT * FROM balance_transactions WHERE user_id=? ORDER BY id DESC'):null;if($rows){$rows->execute([$u['id']]);$rows=$rows->fetchAll();}else $rows=[];?><!doctype html><html lang="<?=e($LANG)?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Transactions — WDH</title><link rel="stylesheet" href="assets/css/style.css?v=wdh-ui-v8"><link rel="stylesheet" href="assets/css/catalog.css?v=wdh-ui-v8"></head><body><?php require __DIR__.'/includes/header.php';?><main class="simple-page"><div class="breadcrumbs">Home › Client Portal › Transactions</div><h1>Account Transactions</h1><div class="admin-table"><?php if(!$rows):?><div class="empty">No transactions yet.</div><?php else:foreach($rows as $r):?><div class="admin-row"><strong><?=e(ucfirst($r['type']))?></strong><span><?=money($r['amount'],'BDT')?></span><small><?=e($r['reference']??'')?> · <?=e($r['status'])?> · <?=e($r['created_at'])?></small></div><?php endforeach;endif;?></div></main><?php require __DIR__.'/includes/footer.php';?></body></html>
